                       'signs, missing feet, foreign charger. Photograph if policy allows.</div></div><div '
                       'class="demo-step"><span class="n">4</span><div>Confirm the outlet works with a known-good lamp '
                       'or phone charger.</div></div><div class="demo-step"><span class="n">5</span><div>Try the '
                       'user’s charger, then a known-good charger of the correct wattage. Note LED behavior on brick '
                       'and laptop.</div></div><div class="demo-step"><span class="n">6</span><div>If still dark: '
                       'remove external devices, hold power 15–30 seconds to discharge residual power, '
                       'retry.</div></div><div class="demo-step"><span class="n">7</span><div>Only after power is '
                       'restored (or ruled out) move to boot troubleshooting. Document every step and '
                       'result.</div></div><div class="demo-step"><span class="n">8</span><div>If parts or data '
