                       '<section id="s1" class="sublesson"><h3>Core concepts</h3>\n'
                       '<p>UEFI initializes hardware and launches the OS bootloader. If handoff fails, OS repair never '
                       'starts—so reinstall Windows is often the wrong first move.</p>\n'
                       '<p>Common settings: boot order, virtualization, Secure Boot, display selection, memory '
