                       '<section class="sublesson"><h3>CPU install and thermal reality</h3>\n'
                       '<p>LGA sockets seat the CPU without bending pins on the processor; force is still the enemy. '
                       'Align indicators, lower the load plate evenly, and never power on without a cooler path.</p>\n'
                       '<p>Thermal paste is a thin interface, not frosting. Too little leaves air gaps; too much can '
