                       '<section id="s1" class="sublesson"><h3>Core concepts</h3>\n'
                       '<p>HDDs: capacity and cost, higher latency. SATA SSD: responsiveness. NVMe: PCIe '
                       'bandwidth—confirm M.2 keying and shared SATA lanes. Verify firmware/OS detection before '
                       'imaging.</p>\n'
                       '<div class="analogy-box"><div class="analogy-label">Analogy · Roads and on-ramps</div>\n'
                       '<p>Storage is where files live when power is off. An HDD is like a warehouse with a single '
                       'forklift—large and cheap, but slow to fetch one item. A SATA SSD is a small warehouse with '
