                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Storage paths and data risk</h3>\n'
                       '<p>HDDs, SATA SSDs, and NVMe devices differ in interface, latency, and failure modes. NVMe '
                       'typically rides PCIe lanes; SATA devices share a different controller path. Cabling, mode '
                       '(AHCI), and driver health all matter.</p>\n'
                       '<p>RAID can provide availability or performance depending on level—it is not a substitute for '
                       'backups. RAID 1 mirrors; RAID 0 stripes without safety; RAID 5/6 add parity with rebuild risk; '
