                       'complete.</p></div>\n'
                       '<section id="s1" class="sublesson"><h3>Core concepts</h3>\n'
                       '<p>RAID 0 stripes without safety. RAID 1 mirrors. RAID 5 needs parity across 3+ disks. RAID 10 '
                       'combines. Arrays do not stop deletion, ransomware, or site loss—backups do.</p>\n'
                       '<div class="analogy-box"><div class="analogy-label">Analogy · Convoy of trucks</div>\n'
                       '<p>RAID is how multiple disks work together. Mirroring (RAID 1) is two trucks carrying '
                       'identical cargo—if one crashes, the other still has the load. Striping (RAID 0) splits cargo '
                       'across trucks for speed, but if one truck is lost, part of the cargo is gone. Important: RAID '
                       'is not a backup. Backup is a copy stored somewhere else, like a spare cargo vault in another '
                       'city.</p></div>\n'
