                       'complete.</p></div>\n'
                       '<section id="s1" class="sublesson"><h3>Core concepts</h3>\n'
                       '<p>Size for peak load plus margin. 24-pin and CPU EPS both matter. Never open a PSU; replace '
                       'as a unit. Undersized power fails under load and mimics software bugs.</p>\n'
                       '<div class="analogy-box"><div class="analogy-label">Analogy · Water main</div>\n'
