                       '\n'
                       '<section class="sublesson"><h3>Power delivery and intermittent faults</h3>\n'
                       '<p>Undersized or failing PSUs create mysteries: random reboots, GPU instability, USB devices '
                       'dropping. Calculate approximate load from CPU, GPU, drives, and peripherals with headroom—not '
                       'marketing peak numbers alone.</p>\n'
                       '<p>Know the main ATX 24-pin, CPU/EPS, PCIe power, and SATA power connectors. Modular cables '
                       'are not universal across brands; mismatched cables can damage hardware.</p>\n'
                       '<p>When testing, use known-good power and minimal parts boot (CPU, one stick RAM, onboard '
                       'video if available) to isolate.</p>\n'
