                       '</section>\n'
                       '\n'
                       '<section id="deep-practice" class="sublesson"><h3>Practice standard for this lesson</h3>\n'
                       '<p>After studying <strong>4.3 Print Path Troubleshooting</strong>, you should be able to walk '
