                       '<p>Build a short checklist (5–9 steps) you would actually use on a ticket. Include what “good” '
                       'looks like at each step and what you will write in the ticket if the step fails.</p>\n'
                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Memory as a system, not a stick</h3>\n'
                       '<p>Capacity, generation, speed, and channel population interact. A single stick may work but '
                       'leave performance on the table; mismatched kits can refuse to train or run unstable.</p>\n'
                       '<p>When diagnosing no-POST or intermittent faults, reseat modules, try known-good sticks, and '
                       'test slots independently. Note ECC vs non-ECC and registered vs unbuffered requirements for '
                       'workstation/server boards.</p>\n'
                       '<p>Document the exact kit part numbers in the asset record. “8 GB RAM” is not enough for '
                       'future replacements.</p>\n'
                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Client addressing in the real world</h3>\n'
                       '<p>A usable IPv4 host typically needs address, mask, gateway, and DNS. Missing any one '
                       'produces a different user story: local-only access, names fail, or no traffic at all.</p>\n'
                       '<p>Private ranges (10/8, 172.16/12, 192.168/16) are normal inside organizations. APIPA '
                       '(169.254/16) usually means DHCP failed—do not “fix” it by setting a random static unless '
                       'policy says so and you understand collisions.</p>\n'
                       '<p>Practice reading <code>ipconfig /all</code> or <code>ip addr</code> and stating the next '
                       'test before changing anything.</p>\n'
                       '</section>\n'
