                       '\n'
                       '<section class="sublesson"><h3>Network operations depth</h3>\n'
                       '<p>Models (OSI/TCP-IP) are maps for isolation: physical, data-link, network, transport, '
                       'application. Good technicians name the layer they are testing.</p>\n'
                       '<p>Subnetting and CIDR are literacy, not trivia—they tell you what is on-link versus routed. '
                       'ARP explains local delivery; routing explains remote.</p>\n'
