                       '<div class="build-on"><strong>Builds on:</strong> 9.4 Capstone — Mixed Environment. Keep that '
                       'idea in mind—this lesson adds the next layer instead of starting from zero.</div>\n'
                       '<div class="plain-english"><h4>In plain English</h4><p>You are learning <strong>10.1 Physical '
                       'and Logical Controls</strong>. We explain ideas the way you would explain them to a teammate '
                       'on day one: what it is, why it matters on a real ticket, and how to check it without guessing. '
