                       '<section id="s1" class="sublesson"><h3>Core concepts</h3>\n'
                       '<p>Layer physical and logical controls. Do not disable security for convenience without '
                       'approval.</p>\n'
                       '<div class="analogy-box"><div class="analogy-label">Analogy · Castle layers</div>\n'
                       '<p>Gate, vault, limited master keys. In simple terms: connect this idea to something you '
