                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Security is part of every ticket</h3>\n'
                       '<p>Least privilege, MFA, encryption, and physical controls reduce blast radius. Support '
                       'shortcuts (shared admin passwords, disabling security tools “temporarily”) create '
