                       '<p>Build a short checklist (5–9 steps) you would actually use on a ticket. Include what “good” '
                       'looks like at each step and what you will write in the ticket if the step fails.</p>\n'
                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Network operations depth</h3>\n'
                       '<p>Models (OSI/TCP-IP) are maps for isolation: physical, data-link, network, transport, '
                       'application. Good technicians name the layer they are testing.</p>\n'
                       '<p>Subnetting and CIDR are literacy, not trivia—they tell you what is on-link versus routed. '
                       'ARP explains local delivery; routing explains remote.</p>\n'
                       '<p>VLANs segment broadcast domains; misassigned access ports look like “the network is down” '
                       'to one desk. Wireless adds authentication, interference, and roaming variables. PoE budgets '
                       'matter when APs and phones reboot randomly.</p>\n'
                       '<p>Firewalls and NAT change what paths exist. When testing, compare on-net vs off-net behavior '
                       'and capture whether the failure is policy or reachability.</p>\n'
                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Beyond the quiz</h3>\n'
                       '<p>Assessment items sample knowledge; they cannot cover every failure mode you will see. For '
                       '<strong>3.1 Routing Roles</strong>, prioritize understanding dependencies: what this component '
