                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Client addressing in the real world</h3>\n'
                       '<p>A usable IPv4 host typically needs address, mask, gateway, and DNS. Missing any one '
                       'produces a different user story: local-only access, names fail, or no traffic at all.</p>\n'
                       '<p>Private ranges (10/8, 172.16/12, 192.168/16) are normal inside organizations. APIPA '
                       '(169.254/16) usually means DHCP failed—do not “fix” it by setting a random static unless '
                       'policy says so and you understand collisions.</p>\n'
                       '<p>Practice reading <code>ipconfig /all</code> or <code>ip addr</code> and stating the next '
                       'test before changing anything.</p>\n'
                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Beyond the quiz</h3>\n'
                       '<p>Assessment items sample knowledge; they cannot cover every failure mode you will see. For '
                       '<strong>4.1 DHCP Deep Dive</strong>, prioritize understanding dependencies: what this '
                       'component or process needs upstream, and what breaks downstream when it fails.</p>\n'
                       '<p>Create one lab or paper scenario of your own: starting symptom, three plausible causes, the '
                       'check that discriminates between them, and the documentation you would leave. That exercise '
                       'builds IT judgment more than rereading a single definition.</p>\n'
                       '<ul>\n'
                       '<li>Explain the topic in plain language to a non-technical user.</li>\n'
                       '<li>List two mistakes a new technician commonly makes here.</li>\n'
                       '<li>Identify when this issue should be escalated rather than forced.</li>\n'
                       '</ul>\n'
                       '</section>',
