                       '<section id="s1" class="sublesson"><h3>Core concepts</h3>\n'
                       '<p>IP works names fail → DNS. Caching delays both breakage and fixes.</p>\n'
                       '<div class="analogy-box"><div class="analogy-label">Analogy · Phone book</div>\n'
                       '<p>Wrong entries wrong destinations. In simple terms: connect this idea to something you '
