                       'tests on a related outage.</li></ol></div>\n'
                       '<table '
                       'class="port-table"><tr><th>Term</th><th>Meaning</th></tr><tr><td><strong>Resolver</strong></td><td>Client '
                       'DNS</td></tr><tr><td><strong>Cache</strong></td><td>Stored answers</td></tr></table>\n'
                       '</section>\n'
                       '<section id="s2" class="sublesson"><h3>Incident application</h3>\n'
