                       '</section>\n'
                       '\n'
                       '<section id="deep-practice" class="sublesson"><h3>Practice standard for this lesson</h3>\n'
                       '<p>After studying <strong>4.2 DNS Deep Dive</strong>, you should be able to walk a peer '
                       'through the topic without notes, then perform the related checks on a lab system or diagram. '
                       'Support work is judged by restored service, reduced risk, and notes another technician can '
