                       '<p>Build a short checklist (5–9 steps) you would actually use on a ticket. Include what “good” '
                       'looks like at each step and what you will write in the ticket if the step fails.</p>\n'
                       '</section>\n'
                       '\n'
                       '<section class="sublesson"><h3>Ports as clues, not magic numbers</h3>\n'
                       '<p>Common ports (22, 53, 80, 443, 3389, etc.) help you form hypotheses quickly. They do not '
                       'replace understanding whether the service is listening, filtered, or failing application '
                       'auth.</p>\n'
                       '<p>When a user cannot reach a web app, test name resolution, TCP reachability, certificate/TLS '
