                       '<div class="live-demo"><h4>Live demonstration habit</h4><p>When you study this lesson on a lab '
                       'PC or diagram, speak each check out loud in order. If you cannot perform a step, mark it and '
                       'return to the earlier lesson that taught that skill before treating this topic as '
                       'complete.</p></div>\n'
                       '<section id="s1" class="sublesson"><h3>Core concepts</h3>\n'
                       '<p>NAT rewrites at edge. Firewall denies look like app outages—ask what changed.</p>\n'
                       '<div class="analogy-box"><div class="analogy-label">Analogy · Mailroom + security</div>\n'
                       '<p>Rewrite vs door policy. In simple terms: connect this idea to something you already '
                       'understand in daily life, then map each part of the comparison back to the technical pieces '
                       'named above.</p></div>\n'
