_CIWT_DEEPEN_APPLIED = True
_CIWT_DEEPEN_MAP = {
    'Motherboards, Form Factors': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — expansion limits &amp; form factor</h4>\n<p>When a build guide calls for a full-height GPU and dual dual-channel memory on a mini-ITX board, the constraint is not “Windows refuses GPUs.” It is clearance, slot count, and power delivery. ATX gives more PCIe slots and cooler room; mini-ITX often offers a single mechanical x16 slot that may be electrically x4 on some small boards—bandwidth drops even if the card fits.</p>\n<p><strong>Analogy:</strong> Choosing a form factor is like choosing a workshop size. A larger shop does not make you a better mechanic by itself, but it determines which tools and projects fit.</p>\n<p><strong>Live demo idea:</strong> Open a board manual and find (1) M.2 slot sharing with SATA ports, (2) which DIMM slots form channel A/B, (3) maximum GPU length. Students should predict a failure mode before assembling.</p>\n</div>',
    'Firmware: UEFI': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — Secure Boot &amp; lab images</h4>\n<p>Secure Boot is designed to start only trusted bootloaders. A training image that needs an unsigned legacy path is a <em>controlled exception</em>, not a permanent hardening removal. Procedure: document the exception, complete the lab, restore Secure Boot/TPM settings, and record the change ticket.</p>\n<p>If Windows Hello or BitLocker was bound to TPM and TPM is cleared, plan re-enrollment and recovery keys—do not treat a TPM clear as a casual toggle.</p>\n</div>',
    'Storage Technologies': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — NVMe not visible to the installer</h4>\n<p>If BIOS lists an NVMe device on a PCIe path but the OS installer only shows a SATA HDD, verify: UEFI vs legacy boot mode, storage controller mode, whether the M.2 slot shares lanes with a disabled SATA port, and that the installer media includes drivers when required. Do not assume “the SSD is dead” until the path is confirmed.</p>\n<p><strong>Analogy:</strong> The drive can be healthy but sitting on a closed hallway (disabled lane/port). Opening the correct door in firmware matters more than reseating at random.</p>\n</div>',
    'RAID and Backup': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — RAID 5 rebuild risk</h4>\n<p>RAID 5 tolerates one disk failure. During rebuild, a second failure can destroy the array. That is why failed disks are replaced promptly, spares matter, and RAID is never a substitute for backups against deletion, ransomware, or site loss. RAID = availability against drive failure; backup = recovery against broader data loss.</p>\n</div>',
    'Power Supplies': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — load shutdowns with normal temperatures</h4>\n<p>If a system is stable idle but shuts down only under GPU/CPU load while temperatures look fine, suspect PSU wattage or 12V capacity, weak cables, or shared power limits—not “DNS” or “wrong VLAN.” Measure or estimate combined TDP and compare to continuous PSU rating with headroom.</p>\n</div>',
    'IPv4 Addressing': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — sizing a subnet</h4>\n<p>Need about 25 hosts without wasting a full /24 when policy allows tighter space? A /27 (255.255.255.224) provides 30 usable addresses. A /30 provides only 2 usable hosts—typical for point-to-point links, not a user LAN. Always separate network and broadcast addresses from usable hosts.</p>\n<p><strong>Worked idea:</strong> Write the mask, count host bits, compute 2^n − 2, then verify the first and last usable addresses before deploying DHCP.</p>\n</div>',
    'Ports, Protocols': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — firewall vs reachability</h4>\n<p>Ping can succeed while RDP fails if ICMP is allowed but TCP 3389 is blocked. Test the service port that matters. Blocking outbound 445 breaks SMB shares first—not DNS or ARP. HTTPS checks belong on 443 with attention to certificates, not “ping only.”</p>\n</div>',
    'Connectivity Isolation': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — gateway up, Internet dead</h4>\n<p>If a host pings gateway and LAN peers but traceroute dies at the gateway toward the Internet, focus upstream: NAT, ISP path, firewall policy—not local disk SMART. APIPA (169.254.x.x) with link light off points to Layer 1/2 or disabled switchport before blaming DHCP scope alone.</p>\n</div>',
    'Repair Tools': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — SFC then DISM</h4>\n<p>When <code>sfc /scannow</code> fails repeatedly, the component store may be unhealthy. DISM restorehealth against a known-good source repairs the store that SFC relies on. For a volume that appears raw after a crash, prefer recovery media and offline repair before destructive <code>diskpart clean</code>.</p>\n</div>',
    'Linux CLI': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — permission denied on scripts</h4>\n<p>Readable is not executable. Use <code>chmod +x</code> or invoke via <code>bash script.sh</code>. Long-term binding to privileged ports should use capabilities or a reverse proxy—not a permanent root shell. OOM killer messages point to memory pressure, not DNS TTL.</p>\n</div>',
    'Physical and Logical': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — MFA passed, access denied</h4>\n<p>Conditional access may require a compliant device even after MFA succeeds. Least privilege means help desk and service accounts get only what they need; local admin for “installing printers” is usually replaced by delegated install or managed deployment.</p>\n</div>',
    'Malware Response': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — persistence and IR order</h4>\n<p>Isolate, identify/research, remove persistence (Run keys, scheduled tasks), remediate, verify, document. Preserve evidence when policy requires imaging before reimage. Phishing reported before a click still needs indicators recorded and checks that credentials were not entered elsewhere.</p>\n</div>',
    'Change Control': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — change window discipline</h4>\n<p>If a risky step remains with ten minutes left in the window, stop or roll back per plan rather than overrun into business hours without approval. Firewall changes without tickets that drop traffic are process failures, not “heroics.”</p>\n</div>',
    'Network Models': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — what each hop rewrites</h4>\n<p>Routers decrement TTL/hop limit and rewrite Layer-2 addressing each hop; they do not normally rewrite application payloads. TCP uses SYN/SYN-ACK/ACK; UDP does not. Prefer UDP for some real-time streams where occasional loss is tolerable—not for ordered financial transactions.</p>\n</div>',
    'Switching, VLANs': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — access ports in different VLANs</h4>\n<p>Two switches linked with access ports in different VLANs do not create inter-VLAN routing by themselves. You need a router or Layer-3 interface. Trunks carry tagged VLANs (802.1Q). STP blocks ports to prevent loops while keeping redundancy.</p>\n</div>',
    'Routing, WAN': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — VPN up, no traffic</h4>\n<p>When a site-to-site tunnel is up but applications fail, inspect traffic selectors (interesting traffic) and routing into the tunnel—not toner levels. MTU/PMTUD black holes stall large payloads while small packets succeed.</p>\n</div>',
    'DHCP, DNS, NAT': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — DNS cache and NAT tradeoffs</h4>\n<p>After updating an A record, clients may still resolve the old address until TTL expires. Many-to-one NAT requires extra mappings for inbound services. Rogue DHCP handing wrong gateways produces “has an address but wrong path” symptoms.</p>\n</div>',
    'Monitoring, Hardening': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — zero trust &amp; management plane</h4>\n<p>Zero trust emphasizes continuous verification and least privilege regardless of location. Harden devices with AAA, SSH/HTTPS management, ACLs on management access, and centralized logging—not Telnet with shared passwords.</p>\n</div>',
    'Network Troubleshooting': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — method</h4>\n<p>Change one variable when practical. High utilization with latency under load suggests saturation. Traceroute stars may mean ICMP TTL-exceeded is filtered while forwarding still works. Wrong static mask on a /22 LAN causes partial connectivity because on-link assumptions are wrong.</p>\n</div>',
    'OSI and TCP/IP': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — hops and headers</h4><p>Each router hop rewrites Layer-2 addressing and decrements TTL/hop limit. Application payload is not rewritten by ordinary IP forwarding. TCP establishes with SYN, SYN-ACK, ACK; UDP does not.</p></div>',
    'Addressing Ideas': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — masks that matter</h4><p>A /28 has 14 usable hosts; a /30 has 2 (point-to-point). 192.168.10.0/23 includes 192.168.11.50 but not 192.168.12.10. Wrong static mask on a /22 LAN causes partial connectivity.</p></div>',
    'TCP versus UDP': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — choosing transport</h4><p>Prefer UDP when occasional loss is acceptable for latency (many real-time designs). Prefer TCP when ordered reliable delivery is required.</p></div>',
    'Switching Basics': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — loops and edge</h4><p>STP blocks to prevent loops. BPDU Guard protects access ports from unexpected BPDUs. Err-disable after flapping is a protection feature, not random failure.</p></div>',
    'VLANs and Trunks': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — inter-VLAN reality</h4><p>Access ports in different VLANs need a router or L3 interface to talk. Trunks carry 802.1Q tags. A wall jack on VLAN 1 will not place a user in VLAN 40 until the switchport matches design.</p></div>',
    'Copper Fiber': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — media choice</h4><p>Long building runs favor fiber. Split pairs fail certification despite continuity. Optical power meters and OTDRs characterize light and locate faults.</p></div>',
    'Routing Roles': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — adjacency is not enough</h4><p>OSPF may be adjacent yet missing routes—check areas, network statements, filters, LSDB. HSRP/VRRP provides first-hop redundancy for clients.</p></div>',
    'WAN Handoffs': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — tunnel policy</h4><p>VPN “up” without interesting traffic or correct routing still fails applications. Dual-homed BGP should shift traffic when one provider fails if policy is correct.</p></div>',
    'Enterprise WLAN': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — capacity and enterprise auth</h4><p>High 2.4 GHz utilization pushes design toward 5/6 GHz. WPA2/WPA3-Enterprise with 802.1X beats a shared city-wide PSK.</p></div>',
    'DHCP Deep': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — scope and rogues</h4><p>Exhausted scopes and rogue servers both produce intermittent addressing problems. Fix capacity and remove rogues.</p></div>',
    'DNS Deep': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — TTL and split horizon</h4><p>Updated records wait on TTL. Split-horizon DNS returns different answers internally vs externally. Anycast can steer clients to the nearest instance of a service address.</p></div>',
    'NAT and Firewall': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — policy direction</h4><p>ACL direction and interface placement matter. Stateful rules still need a path for the initial flow. DMZs separate Internet-facing services from internal trust.</p></div>',
    'Monitoring Signals': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — visibility</h4><p>NetFlow/IPFIX give flow metadata. Encrypted C2 needs behavioral and endpoint telemetry. Centralize syslog for IR correlation.</p></div>',
    'Management Plane': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — harden management</h4><p>SSH/HTTPS, AAA, management ACLs, disable unused ports, control-plane policing—not Telnet with shared passwords.</p></div>',
    'Segmentation': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — blast radius</h4><p>Segmentation limits east-west movement. Zero trust: verify continuously, least privilege everywhere.</p></div>',
    'Method Under Pressure': '<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)"><h4>Scenario depth — discipline</h4><p>One change at a time when practical. Verify with the stakeholder. Document. High utilization plus latency under load is saturation until proven otherwise.</p></div>',
    'Support Technician Role': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — intake quality</h4>\n<p>A good ticket captures: who is affected, when it started, wired vs wireless, recent changes, and impact. Vague tickets like “Internet broken” force rework. Distinguish break/fix (something that worked stopped) from a service request (new access) and from a security incident (possible compromise).</p>\n<p><strong>Analogy:</strong> A field medic’s first report needs location, injury type, and severity—not a novel. Same for IT intake.</p>\n</div>',
    'Workplace and ESD': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — ESD and safety order</h4>\n<p>Power down and unplug before opening cases when policy requires it. Use a grounded wrist strap and ESD-safe mat when handling boards and modules. Swollen batteries are hazardous—do not puncture or keep charging; isolate per safety procedure.</p>\n<p>Trip hazards, lifting limits, and eye protection for toner/chemicals matter as much as “technical” skill.</p>\n</div>',
    'Ticketing, Documentation': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — handoff</h4>\n<p>When escalating, list symptoms, steps already tried, and timestamps. Closing a ticket without user confirmation risks false “resolved” status. Change control is not bureaucracy for its own sake—it coordinates risk, timing, and rollback.</p>\n</div>',
    'Professional Communication': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — privacy in the field</h4>\n<p>Do not discuss other users’ issues in open spaces. Shoulder-surfing controls (privacy screens) and screen-lock habits protect data in transit through human error. Speak in plain language; jargon without explanation frustrates customers and hides whether they understood the next step.</p>\n</div>',
    'CPUs, Cooling': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — thermal paste and throttling</h4>\n<p>Thermal paste goes in a thin, appropriate layer between the CPU heat spreader and cooler base—not smeared across the board. High idle temperatures after a messy paste job often mean excess compound acting as an insulator. Under load, if temps are fine but the system shuts down, look at power delivery before assuming “CPU failure.”</p>\n</div>',
    'Memory Technologies': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — channels and generation</h4>\n<p>DDR4 and DDR5 are not interchangeable in the same slot. Dual-channel needs matched modules in the channel pair the board manual documents (often slots 2 and 4, not 1 and 2). ECC registered server modules will not initialize on many consumer boards that only list unbuffered non-ECC support—the memory controller and firmware must support the module class.</p>\n</div>',
    'POST Isolation': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — minimal configuration</h4>\n<p>Long continuous beep with no display often points to memory or video path issues. Reseat RAM, try one stick, known-good module, and onboard video if available. Removing a discrete GPU that restores video isolates the discrete card or its power/slot path. Change one variable at a time.</p>\n</div>',
    'Ports, Cables': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — docks and displays</h4>\n<p>A USB-C dock may offer DisplayPort-alt-mode video only if the laptop port and cable support it. Bandwidth limits can cap external monitor count. HDMI and DisplayPort carry video and often audio; they are not power or network links.</p>\n</div>',
    'Laptop FRUs': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — hinge and battery</h4>\n<p>A laptop that only charges with the lid at a certain angle often has a damaged hinge cable or connector under flex. Swollen batteries that lift the trackpad require safe isolation—not “keep using until it dies.”</p>\n</div>',
    'Mobile Networking': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — MDM and exceptions</h4>\n<p>If MDM blocks USB file transfer, use the approved exception workflow—not a jailbreak. Corporate email and VPN profiles often depend on device compliance; “MFA worked but app denied” can mean conditional access still requires a compliant device.</p>\n</div>',
    'Print Path': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — ghosting</h4>\n<p>Ghosted previous images with normal fuser temperature often implicate a worn drum or cleaning blade retaining toner—not the default gateway. Isolate: test page from printer menu vs print from OS vs network path.</p>\n</div>',
    'SOHO Wireless': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — SOHO hardening</h4>\n<p>Prefer WPA2/WPA3 with a strong unique passphrase over legacy WEP/TKIP. Change default admin credentials on the router. Separate guest Wi-Fi from the LAN when the device supports it. Channel congestion on 2.4 GHz is a capacity problem—move capable clients to 5 GHz when available.</p>\n</div>',
    'Hypervisors and VMs': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — clones and identity</h4>\n<p>Cloning a domain-joined VM without generalizing identity yields duplicate names and IPs on the LAN. Sysprep/generalize (or equivalent) and unique network identity prevent both clones from fighting for the same identity.</p>\n</div>',
    'Cloud Service Models': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — shared responsibility</h4>\n<p>IaaS: you harden the OS and apps more. SaaS: the provider runs more of the stack, but you still manage identities, data classification, and access. “In the cloud” does not mean “no security work.”</p>\n</div>',
    'Virtual Networking': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — snapshots</h4>\n<p>Snapshots are recovery points for change windows, not a backup strategy against ransomware or site loss. Promiscuous mode on a shared host without approval can expose other tenants’ traffic depending on isolation—treat as a security change.</p>\n</div>',
    'Structured Process': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — method</h4>\n<p>Identify the problem, establish a theory, test the theory, plan action, implement, verify, document. Changing three variables at once destroys attribution—you cannot tell which change fixed or broke the system.</p>\n</div>',
    'Fault Domains': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — isolate the domain</h4>\n<p>Ask: is this one user, one VLAN, one building, or everything? One desk with APIPA and a dark switch LED is Layer 1/2 or port config before a campus-wide DHCP redesign.</p>\n</div>',
    'Verification and Handoff': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — verify with the user</h4>\n<p>After a fix, confirm the original symptom is gone with the requester when possible. Document solution so the next technician does not repeat dead ends.</p>\n</div>',
    'Clean vs In-Place': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — UEFI and GPT</h4>\n<p>Native UEFI installs typically use GPT. MBR is limited in partition count and disk size relative to GPT. Match the installer mode to firmware mode to avoid boot loops.</p>\n</div>',
    'Baseline Configuration': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — time and domain</h4>\n<p>Kerberos is sensitive to clock skew. A domain client minutes off can fail logons intermittently. Baseline images should include correct time sync, update posture, and least-privilege local policy.</p>\n</div>',
    'macOS Support': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — cross-platform habits</h4>\n<p>File sharing, certificates, and VPN clients differ by platform, but the troubleshooting order stays familiar: confirm network path, authentication, then application. Document the macOS-specific tools your organization supports.</p>\n</div>',
    'Cross-Platform Access': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — identity is shared</h4>\n<p>SSO and MFA often span Windows, mobile, and SaaS. When access fails after MFA, check conditional access and device compliance before reinstalling apps at random.</p>\n</div>',
    'Support Hygiene': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — credentials</h4>\n<p>No shared admin passwords on monitors. Rotate secrets found in scripts or repos. Least privilege reduces blast radius when an account is compromised.</p>\n</div>',
    'Symptom Patterns': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — slow logon</h4>\n<p>Slow logon can be profile, GPO, name resolution, or disk. Compare a local account vs domain, wired vs wireless, and Event Viewer for timeouts—do not jump straight to reimage.</p>\n</div>',
    'Isolation Techniques': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — safe mode and clean boot</h4>\n<p>Clean boot / selective startup and Safe Mode help separate third-party services from OS faults. Note what you disable so you can reverse it.</p>\n</div>',
    'Repair vs Rebuild': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — data first</h4>\n<p>Prefer repair and restore of user data before destructive rebuilds. If policy requires reimage after compromise, preserve evidence first when the IR plan says so.</p>\n</div>',
    'Privacy and Policy': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — disposal</h4>\n<p>Retired drives need approved cryptographic erase or physical destruction—not a single quick format. Policy exists to protect people and the mission, not to slow tickets arbitrarily.</p>\n</div>',
    'Recovery Awareness': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — backup test</h4>\n<p>The strongest validation of backup is a periodic restore test to a non-production target—not a green job status alone. RAID is not a backup.</p>\n</div>',
    'Pattern Library': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — common network patterns</h4>\n<p>APIPA + dark port LED → physical/port. DNS works, web fails on captive portal → policy until login. Tunnel up, apps fail → selectors/routing. Large transfers stall, small packets work → MTU/PMTUD path issues.</p>\n</div>',
    'Verification and Documentation': '\n<div class="scenario-lab mt-4 p-3 rounded" style="background:var(--surface-3);border:1px solid var(--surface-4)">\n<h4>Scenario depth — close the loop</h4>\n<p>After network changes, verify with the affected user or monitoring dashboard, then document what changed and why. Future you will need it.</p>\n</div>',
}

def _apply_ciwt_deepen(pack):
    for ch in pack:
        if not isinstance(ch, dict):
            continue
        for les in ch.get('lessons', []):
            title = (les.get('title') or '')
            html = les.get('html') or ''
            if 'scenario-lab' in html:
                continue
            for key, block in _CIWT_DEEPEN_MAP.items():
                if key.lower() in title.lower():
                    les['html'] = html + block
                    break

_apply_ciwt_deepen(APLUS)
_apply_ciwt_deepen(NETPLUS)

